# «خبر و گزارش بازار»: سه تب (خبر / قیمت‌ها / مقایسه)، عکس در ردیف‌ها، خبر از سایت‌ها (ساختگی)، برگشت به گزارش
import asyncio,sys,json
sys.path.insert(0,'/home/claude/PerfumePrice/tests')
from rep_common import *
OK=[];BAD=[]
def chk(n,c,i=''):
    (OK if c else BAD).append(n); print(('PASS ' if c else 'FAIL ')+n+(' '+str(i)[:200] if i!='' else ''))
OVF="""(function(){var r=document.getElementById('mkr'),bad=[];[].forEach.call(r.querySelectorAll('.mkr,.mkr *,.nwc,.nwc *,.hl,.hl *,.mki,.mkk'),function(e){var b=e.getBoundingClientRect();if(b.width&&(b.right>innerWidth+1||b.left<-1))bad.push(e.className+':'+Math.round(b.left)+'-'+Math.round(b.right))});return {bad:bad.slice(0,4),sw:r.scrollWidth,cw:r.clientWidth}})()"""
async def main():
    async with async_playwright() as p:
        flat,mid0=await first_flat(p)
        seed=make_seed(flat)
        # ---------- ۱) جریانِ اصلی ----------
        b,ctx,pg,errs=await new_page(p,360,780,'light',extra=pre_js(seed)+news_mock_js())
        await pg.goto('file://'+ROOT+'/index.html'); await wait_ready(pg,180000); await pg.wait_for_timeout(1500)
        ev=pg.evaluate
        chk('no news request before the report is opened',await ev("window.__NEWSCALLS.length")==0)
        await ev("document.getElementById('nw').click()"); await pg.wait_for_timeout(2500)
        chk('report opens on the news tab',await ev("document.getElementById('mk').classList.contains('on') && document.querySelector('#mkt2 .on').dataset.t")=='news')
        tabs=await ev("[].map.call(document.querySelectorAll('#mkt2 button'),function(b){return b.dataset.t+':'+b.innerText.replace(/[\\d۰-۹\\s]+$/,'')})")
        chk('three tabs: news, chg, cmp',tabs==['news:خبر','chg:قیمت‌ها','cmp:مقایسه'],tabs)
        chk('prices tab shows how many perfumes changed (counter)',await ev("!!document.querySelector('#mkt2 [data-t=chg] i') && document.querySelector('#mkt2 [data-t=chg] i').innerText.length>0"))
        chk('title says news and report',await ev("document.querySelector('#mk .mkt').innerText")=='خبر و گزارش بازار')
        chk('news tab is the feed: no old headline rows, no photo rows',await ev("document.querySelectorAll('#mkr .hl').length")==0 and await ev("document.querySelectorAll('#mkr .mkr.pr').length")==0)
        nw=await ev("[].map.call(document.querySelectorAll('#mkr .nwc'),function(b){return {t:b.querySelector('.nft').innerText,u:b.dataset.u,img:!!b.querySelector('img.nimg'),em:b.querySelector('.nfs b').innerText+'، '+(b.querySelector('.nfs small')||{innerText:''}).innerText}})")
        chk('all news cards shown (liliome 4 + safir 2 + mag 1; the phone article is filtered)',len(nw)==7,len(nw))
        txt=' | '.join(x['t'] for x in nw)
        chk('news from the shop sites',all(k in txt for k in ['راهنمای انتخاب عطر زمستانی','عطرهای تازه رسیده به سفیر']),txt)
        chk('non-perfume digikala-mag article is filtered out','گوشی' not in txt)
        chk('news sorted newest first',nw[0]['em'].startswith('لیلیوم') or nw[0]['em'].startswith('مجله'),[x['em'] for x in nw])
        chk('news cards have image (wp featured + rss content img); others get a bottle frame',sum(1 for x in nw if x['img'])>=2 and await ev("document.querySelectorAll('#mkr .nwc .nfi.ph svg').length")==len(nw)-sum(1 for x in nw if x['img']),[x['img'] for x in nw])
        chk('news date uses comma, not a dot that looks like a zero','·' not in ' '.join(x['em'] for x in nw),[x['em'] for x in nw])
        chk('news urls are the shops',all(x['u'].startswith(('https://liliome.com','https://www.safirstores.com','https://www.digikala.com')) for x in nw))
        nc=await ev("window.__NEWSCALLS.length")
        chk('news fetched on open (wp-json for 4 sites + rss fallbacks)',4<=nc<=12,nc)
        await ev("window.__lastOpen=''; document.querySelector('#mkr .nwc').click()"); await pg.wait_for_timeout(200)
        chk('tapping news opens its link',await ev("window.__lastOpen")==nw[0]['u'],await ev("window.__lastOpen"))
        chk('stays on the report after tapping news',await ev("document.getElementById('mk').classList.contains('on')"))
        st=json.loads(await ev("localStorage.getItem('pp.news')") or '{}')
        chk('news saved for next time',len(st.get('items',[]))>=5 and st.get('t',0)>0,len(st.get('items',[])))
        chk('no unseen-news dot while report is open',not await ev("document.getElementById('nw').classList.contains('nu')"))
        chk('no more-button any more (everything is in the feed)',await ev("document.querySelectorAll('#mkr .mkmore[data-s=news]').length")==0)
        chk('refresh button is at the end of the feed',await ev("(function(){var b=document.querySelector('#mkr [data-act=news]');return !!b && !b.disabled && b.innerText.indexOf('تازه‌سازی')>=0})()"))
        chk('status line says when and how often',await ev("(document.querySelector('#mkr .nfst')||{innerText:''}).innerText.indexOf('هر ۳ ساعت')>=0"))
        o=await ev(OVF); chk('news tab: nothing outside the screen',not o['bad'] and o['sw']<=o['cw']+1,o)
        # تیتر → تب مربوط
        await ev("document.getElementById('mkr').scrollTop=0")
        await ev("document.querySelector('#mkt2 [data-t=chg]').click()"); await pg.wait_for_timeout(300)
        chk('prices tab opens from its tab (counter inside the button works)',await ev("document.querySelector('#mkt2 .on').dataset.t")=='chg')
        # تب قیمت‌ها
        t=await ev("document.getElementById('mkr').innerText")
        for s in ['ارزان شده‌اند','گران شده‌اند','دوباره موجود شده‌اند','تازه‌های بازار','ناموجود شده‌اند']: chk('prices tab has '+s,s in t)
        chk('prices tab: good news first (cheaper before dearer)',t.index('ارزان شده‌اند')<t.index('گران شده‌اند'))
        rows=await ev("[].map.call(document.querySelectorAll('#mkr .mkr'),function(r){return r.innerText.replace(/\\n/g,' | ')})")
        chk('drop row shows before and now',any('ارزان‌تر' in r and 'قبلاً:' in r and 'الان:' in r for r in rows))
        chk('rise row shows before and now',any('گران‌تر' in r and 'قبلاً:' in r and 'الان:' in r for r in rows))
        chk('sparklines drawn',await ev("document.querySelectorAll('#mkr .spk polyline').length")>=2)
        chk('gone row keeps last price',any('ناموجود آزمایشی' in r and '۲٬۵۰۰٬۰۰۰' in r for r in rows),[r for r in rows if 'ناموجود آزمایشی' in r])
        chk('every row has a photo tile',await ev("document.querySelectorAll('#mkr .mkr.pr').length")==await ev("document.querySelectorAll('#mkr .mkr.pr .mph .tile').length"))
        chk('every row is tappable',await ev("document.querySelectorAll('#mkr .mkr.pr:not([data-m]):not([data-q])').length")==0)
        chk('prices tab: no NaN/undefined/null',all(w not in t for w in ['NaN','undefined','null']))
        o=await ev(OVF); chk('prices tab: nothing outside the screen',not o['bad'] and o['sw']<=o['cw']+1,o)
        # ردیف → صفحه‌ی قیمت روی گزارش؛ برگشت = همان گزارش با همان جای اسکرول
        await ev("document.getElementById('mkr').scrollTop=150"); await pg.wait_for_timeout(100)
        sc0=await ev("document.getElementById('mkr').scrollTop")
        await ev("document.querySelector('#mkr .mkr.pr[data-m]').click()"); await pg.wait_for_timeout(600)
        chk('row opens the perfume page above the report',await ev("document.getElementById('dt').classList.contains('on') && document.getElementById('mk').classList.contains('on')"))
        await ev("window.__back()"); await pg.wait_for_timeout(500)
        chk('back returns to the same report tab',await ev("!document.getElementById('dt').classList.contains('on') && document.getElementById('mk').classList.contains('on') && document.querySelector('#mkt2 .on').dataset.t")=='chg')
        chk('back keeps the scroll place',abs(await ev("document.getElementById('mkr').scrollTop")-sc0)<3,[sc0,await ev("document.getElementById('mkr').scrollTop")])
        # دو بار به همان عطر: تکراری رکورد نمی‌شود، و از دیدنِ دوم هم برمی‌گردد
        # ناموجود → جستجو با نام
        await ev("(function(){var r=[].filter.call(document.querySelectorAll('#mkr .mkr[data-q]'),function(x){return /ناموجود آزمایشی/.test(x.innerText)})[0];if(r)r.click()})()"); await pg.wait_for_timeout(500)
        chk('gone row opens search with its name',await ev("document.getElementById('srch').classList.contains('on') && !document.getElementById('mk').classList.contains('on') && document.getElementById('srq').value.indexOf('ناموجود')>=0"),await ev("document.getElementById('srq').value"))
        await ev("window.__back()"); await pg.wait_for_timeout(300)
        # تب مقایسه
        await ev("document.getElementById('nw').click()"); await pg.wait_for_timeout(500)
        await ev("document.querySelector('#mkt2 [data-t=cmp]').click()"); await pg.wait_for_timeout(300)
        t=await ev("document.getElementById('mkr').innerText")
        for s in ['نتیجه','فروشگاه‌ها با هم','کدام عطر را از کجا بخرم؟']: chk('compare tab has '+s,s in t)
        chk('compare tab: insight cards',await ev("document.querySelectorAll('#mkr .mki').length")>=1)
        chk('compare tab: store rows',await ev("document.querySelectorAll('#mkr .mkr.nl').length")>=3)
        chk('compare tab: deal rows have photos',await ev("document.querySelectorAll('#mkr .mkr.pr .mph .tile').length")>=5)
        n0=await ev("document.querySelectorAll('#mkr .mkr.pr').length")
        await ev("document.querySelector('#mkr .mkch button[data-k=gn][data-v=w]').click()"); await pg.wait_for_timeout(300)
        n1=await ev("document.querySelectorAll('#mkr .mkr.pr').length")
        chk('gender filter works',n1<=n0 and await ev("document.querySelector('#mkr .mkch button[data-v=w]').classList.contains('on')"),[n0,n1])
        await ev("document.querySelector('#mkr .mkch button[data-k=gn][data-v=\"\"]').click()"); await pg.wait_for_timeout(200)
        await ev("document.querySelector('#mkr .mkch button[data-k=sort][data-v=p]').click()"); await pg.wait_for_timeout(300)
        chk('percent sort button on',await ev("document.querySelector('#mkr .mkch button[data-v=p]').classList.contains('on')"))
        hasmore=await ev("document.querySelectorAll('#mkr .mkmore[data-s=cmp]').length")
        if hasmore:
            b0=await ev("document.querySelectorAll('#mkr .mkr.pr').length"); await ev("document.querySelector('#mkr .mkmore[data-s=cmp]').click()"); await pg.wait_for_timeout(300)
            chk('compare: show more adds rows',await ev("document.querySelectorAll('#mkr .mkr.pr').length")>b0)
        o=await ev(OVF); chk('compare tab: nothing outside the screen',not o['bad'] and o['sw']<=o['cw']+1,o)
        chk('compare tab: no NaN/undefined/null',all(w not in t for w in ['NaN','undefined','null']))
        # بسته شدن
        await ev("window.__back()"); await pg.wait_for_timeout(300)
        chk('back closes the report',not await ev("document.getElementById('mk').classList.contains('on')"))
        # باز شدنِ دوباره: بدون دریافتِ تازه (خبرِ تازه دارد)
        n_before=await ev("window.__NEWSCALLS.length")
        await ev("document.getElementById('nw').click()"); await pg.wait_for_timeout(800)
        chk('fresh news is not fetched again on re-open',await ev("window.__NEWSCALLS.length")==n_before,[n_before,await ev("window.__NEWSCALLS.length")])
        chk('re-open starts on the news tab again',await ev("document.querySelector('#mkt2 .on').dataset.t")=='news')
        chk('no page errors (main flow)',not [e for e in errs if 'Failed to load' not in e],errs[:3])
        await b.close()
        # ---------- ۲) اینترنت خراب: خبر نیامد؛ بقیه‌ی گزارش سالم؛ «دوباره امتحان» ----------
        b,ctx,pg,errs=await new_page(p,360,780,'dark',extra=pre_js(seed)+news_mock_js('fail'))
        await pg.goto('file://'+ROOT+'/index.html'); await wait_ready(pg,180000); await pg.wait_for_timeout(1500)
        ev=pg.evaluate
        await ev("document.getElementById('nw').click()"); await pg.wait_for_timeout(2500)
        t=await ev("document.getElementById('mkr').innerText")
        chk('news failed: calm message, no crash','فعلاً خبری از سایت‌ها نرسید' in t and await ev("document.querySelectorAll('#mkr .nwc').length")==0)
        chk('news failed: the other tabs still work (counter still shown)',await ev("!!document.querySelector('#mkt2 [data-t=chg] i')"))
        chk('retry button present',await ev("document.querySelectorAll('#mkr [data-act=news]').length")==1)
        c1=await ev("window.__NEWSCALLS.length")
        await ev("window.__NEWSMODE='ok'; document.querySelector('#mkr [data-act=news]').click()"); await pg.wait_for_timeout(2500)
        chk('retry asks again (even inside the 10-minute pause)',await ev("window.__NEWSCALLS.length")>c1)
        chk('retry shows the news',await ev("document.querySelectorAll('#mkr .nwc').length")>=3)
        await pg.screenshot(path='/tmp/w/shots3/t60_dark.png')
        chk('no page errors (fail mode)',not [e for e in errs if 'Failed to load' not in e],errs[:3])
        await b.close()
        # ---------- ۳) نقطه‌ی قرمزِ خبر نادیده + ذخیره‌ی خراب + آدرسِ بد ----------
        now=int(time.time()*1000)
        good={'t':now-3600000,'notes':{},'items':[{'s':'liliome','sn':'لیلیوم','t':'خبر تازه‌ی ذخیره‌شده','d':now-3600000,'u':'https://liliome.com/x/','x':'متن','img':''},
              {'s':'x','sn':'بد','t':'آدرس بد','d':now,'u':'https://evil.com/p','x':'','img':''},{'s':'x','sn':'بد','t':'js','d':now,'u':'javascript:alert(1)','x':'','img':''},{'bad':1},5,None]}
        pre=pre_js(seed)+"if(!sessionStorage.getItem('nn')){sessionStorage.setItem('nn','1');localStorage.setItem('pp.news',%s);}"%json.dumps(json.dumps(good))
        b,ctx,pg,errs=await new_page(p,360,780,'light',extra=pre+news_mock_js('fail'))
        await pg.goto('file://'+ROOT+'/index.html'); await wait_ready(pg,180000); await pg.wait_for_timeout(1500)
        ev=pg.evaluate
        chk('saved news gives the red dot',await ev("document.getElementById('nw').classList.contains('nu')"))
        await ev("document.getElementById('nw').click()"); await pg.wait_for_timeout(600)
        cards=await ev("[].map.call(document.querySelectorAll('#mkr .nwc .nft'),function(e){return e.innerText})")
        chk('saved news shown, bad urls and junk dropped',cards==['خبر تازه‌ی ذخیره‌شده'],cards)
        chk('opening the report clears the dot',not await ev("document.getElementById('nw').classList.contains('nu')"))
        await ev("window.__back()"); await pg.wait_for_timeout(300)
        chk('dot stays off after closing (news was seen)',not await ev("document.getElementById('nw').classList.contains('nu')"))
        chk('news saved is not refetched while fresh',await ev("window.__NEWSCALLS.length")==0,await ev("window.__NEWSCALLS.length"))
        chk('no page errors (saved news)',not [e for e in errs if 'Failed to load' not in e],errs[:3])
        await b.close()
        b,ctx,pg,errs=await new_page(p,360,780,'light',extra="if(!sessionStorage.getItem('cn')){sessionStorage.setItem('cn','1');localStorage.setItem('pp.news','{\"items\":5}');localStorage.setItem('pp.hist','{{{');}"+news_mock_js())
        await pg.goto('file://'+ROOT+'/index.html'); await wait_ready(pg,180000); await pg.wait_for_timeout(1500)
        ev=pg.evaluate
        await ev("document.getElementById('nw').click()"); await pg.wait_for_timeout(2500)
        t=await ev("document.getElementById('mkr').innerText")
        chk('corrupt saved news + corrupt history: report opens, news refetched',await ev("document.getElementById('mk').classList.contains('on')") and await ev("document.querySelectorAll('#mkr .nwc').length")>=3 and 'undefined' not in t,errs[:2])
        await ev("document.querySelector('#mkt2 [data-t=chg]').click()"); await pg.wait_for_timeout(300)
        t=await ev("document.getElementById('mkr').innerText"); chk('corrupt history: prices tab ok',await ev("document.querySelector('#mkt2 .on').dataset.t")=='chg' and 'undefined' not in t and 'NaN' not in t)
        await b.close()
        # ---------- ۴) عطرِ پنهان‌شده در گزارش نمی‌آید ----------
        pre="if(!sessionStorage.getItem('hh')){sessionStorage.setItem('hh','1');localStorage.setItem('pp.hist',%s);var s=JSON.parse(localStorage.getItem('pp.set')||'{}');s.hide={};s.hide[%s]='x | y';localStorage.setItem('pp.set',JSON.stringify(s));}"%(json.dumps(json.dumps(seed)),json.dumps(mid0))
        b,ctx,pg,errs=await new_page(p,extra=pre+news_mock_js())
        await pg.goto('file://'+ROOT+'/index.html'); await wait_ready(pg,180000); await pg.wait_for_timeout(1500)
        ev=pg.evaluate
        await ev("document.getElementById('nw').click()"); await pg.wait_for_timeout(500)
        await ev("document.querySelector('#mkt2 [data-t=chg]').click()"); await pg.wait_for_timeout(300)
        nr=await ev("[].map.call(document.querySelectorAll('#mkr .mkr'),function(r){return r.innerText})")
        chk('hidden perfume is not in the report (its rise row is gone, drop row stays)',not any('گران‌تر' in r and 'قبلاً' in r for r in nr) and any('ارزان‌تر' in r and 'قبلاً' in r for r in nr),len(nr))
        await b.close()
        # ---------- ۵) صفحه‌ی کوچک و نوشته‌ی بزرگ ----------
        for w,fs in ((320,0),(320,3),(360,3)):
            b,ctx,pg,errs=await new_page(p,w,640,'light',extra=pre_js(seed,fs)+news_mock_js())
            await pg.goto('file://'+ROOT+'/index.html'); await wait_ready(pg,180000); await pg.wait_for_timeout(1500)
            ev=pg.evaluate; tag='w%d fs%d '%(w,fs)
            await ev("document.getElementById('nw').click()"); await pg.wait_for_timeout(2500)
            for tb in ('news','chg','cmp'):
                await ev("document.querySelector('#mkt2 [data-t=%s]').click()"%tb); await pg.wait_for_timeout(300)
                o=await ev(OVF); chk(tag+tb+': nothing outside the screen',not o['bad'] and o['sw']<=o['cw']+1,o)
                tt=await ev("document.getElementById('mkr').innerText"); chk(tag+tb+': no NaN/undefined/null',all(x not in tt for x in ['NaN','undefined','null']))
                # قابل لمس: بالای ۴۴ پیکسل
                small=await ev("[].filter.call(document.querySelectorAll('#mkr button'),function(b){var r=b.getBoundingClientRect();return r.width&&r.height<44}).length")
                chk(tag+tb+': every button is at least 44px tall',small==0,small)
            await pg.screenshot(path='/tmp/w/shots3/t60_%d_%d.png'%(w,fs))
            chk(tag+'no page errors',not [e for e in errs if 'Failed to load' not in e],errs[:3])
            await b.close()
    print(len(OK),'pass',len(BAD),'fail',BAD)
asyncio.run(main())
